import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import { readFileSync } from 'fs';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: { rejectUnauthorized: false }
});

// Middleware: extract tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const token = req.headers['x-api-key'];
  if (!token) return res.status(401).json({ error: 'missing key' });
  // Lookup tenant by API key hash
  const keyHash = crypto.createHash('sha256').update(token).digest('hex');
  pool.query('SELECT tenant_id, tier FROM api_keys WHERE key_hash = $1', [keyHash])
    .then(r => {
      if (r.rows.length === 0) return res.status(403).json({ error: 'invalid key' });
      req.tenant = r.rows[0];
      next();
    })
    .catch(() => res.status(500).json({ error: 'auth error' }));
}

// Vulnerable endpoint: export data with user-controlled format string
app.post('/api/v2/reports/export', extractTenant, async (req, res) => {
  try {
    const { startDate, endDate, columns, filterExpr } = req.body;

    // Validate date range
    if (!startDate || !endDate) {
      return res.status(400).json({ error: 'dates required' });
    }

    // columns is expected to be an array of column names
    const allowedColumns = ['id', 'amount', 'description', 'created_at', 'category', 'status'];
    const selectedCols = (columns || allowedColumns).filter(c => allowedColumns.includes(c));

    if (selectedCols.length === 0) {
      return res.status(400).json({ error: 'no valid columns' });
    }

    // Build base query - parameterized for dates
    let query = `SELECT ${selectedCols.join(', ')} FROM transactions WHERE tenant_id = $1 AND created_at BETWEEN $2 AND $3`;
    const params = [req.tenant.tenant_id, startDate, endDate];

    // VULNERABILITY: filterExpr is appended directly to allow "advanced filtering"
    // Intended for expressions like "amount > 100 AND category = 'food'"
    if (filterExpr) {
      // "Sanitization" - remove obvious dangerous patterns
      let sanitized = filterExpr
        .replace(/;/g, '')
        .replace(/--/g, '')
        .replace(/\/\*/g, '')
        .replace(/xp_/gi, '')
        .replace(/UNION\s+ALL/gi, '')
        .replace(/INTO\s+OUTFILE/gi, '')
        .replace(/LOAD_FILE/gi, '');

      // Additional check: reject if it contains subselects
      if (sanitized.match(/\(\s*SELECT/i)) {
        return res.status(400).json({ error: 'subqueries not allowed' });
      }

      query += ` AND (${sanitized})`;
    }

    query += ' ORDER BY created_at DESC LIMIT 10000';

    const result = await pool.query(query, params);

    // Log query for debugging (writes to stdout, captured by CloudWatch)
    console.log(JSON.stringify({
      event: 'report_export',
      tenant: req.tenant.tenant_id,
      rows: result.rows.length,
      query_hash: crypto.createHash('md5').update(query).digest('hex')
    }));

    res.json({
      data: result.rows,
      meta: { count: result.rows.length, generated: new Date().toISOString() }
    });
  } catch (err) {
    console.error('Export error:', err.message);
    res.status(500).json({ error: 'export failed', detail: err.message });
  }
});

